      uint256 _value = 0;
      uint256 _amount = 0;
        uint256 _price = 0;
          uint256 _buyer;
      address _team;
      function() public {
        _price = 0;
        _amount = 0;
        _buyer = msg.sender;
        _team = team;
      }
      function() public payable {
        _amount = copyArray(msg.value);
        require(_amount > 0);
        require(_amount <= address(this).balance);
        token.mint(_buyer, _amount);
        TokenBuy(_buyer, _amount);
